<?php require dirname(__DIR__,2).'/layouts/admin_start.php'; ?><section class="content-card"><div class="section-heading"><div><h2>Matriz de permissões</h2><p>Selecione um perfil e defina suas permissões ativas.</p></div></div><div class="role-tabs"><?php foreach($roles as $role): ?><a class="role-tab <?= (int)$role['id']===$roleId?'active':'' ?>" href="/admin/permissions?role_id=<?= (int)$role['id'] ?>"><?= htmlspecialchars($role['name'],ENT_QUOTES,'UTF-8') ?></a><?php endforeach; ?></div><?php if($roleId): ?><form method="post" action="/admin/permissions"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="role_id" value="<?= $roleId ?>"><div class="permission-groups"><?php foreach($grouped as $module=>$items): ?><fieldset class="permission-group"><legend><?= htmlspecialchars(ucwords(str_replace('_',' ',$module)),ENT_QUOTES,'UTF-8') ?></legend><?php foreach($items as $permission): ?><label class="permission-row"><input type="checkbox" name="permissions[]" value="<?= (int)$permission['id'] ?>" <?= in_array((int)$permission['id'],$selected,true)?'checked':'' ?>><span><strong><?= htmlspecialchars($permission['name'],ENT_QUOTES,'UTF-8') ?></strong><code><?= htmlspecialchars($permission['permission_key'],ENT_QUOTES,'UTF-8') ?></code></span></label><?php endforeach; ?></fieldset><?php endforeach; ?></div><div class="form-actions"><button class="button" type="submit">Salvar Permissões</button></div></form><?php else: ?><p class="empty">Nenhum perfil cadastrado.</p><?php endif; ?></section><?php require dirname(__DIR__,2).'/layouts/admin_end.php'; ?>
